// Verification for the strict file pipeline.
// Reads every saved stage from disk, checks the arithmetic chain,
// then writes answer.json using the values read back from the saved files.
"use strict";

const fs = require("fs");
const path = require("path");

const failures = [];
function check(name, cond, detail) {
  if (cond) {
    console.log("PASS " + name + (detail ? " (" + detail + ")" : ""));
  } else {
    failures.push(name + (detail ? " (" + detail + ")" : ""));
    console.log("FAIL " + name + (detail ? " (" + detail + ")" : ""));
  }
}

function readNumber(file) {
  if (!fs.existsSync(file)) throw new Error("missing required file: " + file);
  const raw = fs.readFileSync(file, "utf8");
  const trimmed = raw.trim();
  const n = Number(trimmed);
  if (trimmed === "" || !Number.isFinite(n)) {
    throw new Error(file + " does not contain a finite number: " + JSON.stringify(raw));
  }
  return { value: n, raw: raw };
}

const seed = readNumber("seed.txt").value;
const s1 = readNumber("stage1.txt").value;
const s2 = readNumber("stage2.txt").value;
const s3 = readNumber("stage3.txt").value;

// Required file order/existence already proven by readNumber for each stage.
for (const f of ["seed.txt", "stage1.txt", "stage2.txt", "stage3.txt"]) {
  check("exists " + f, fs.existsSync(f), "bytes=" + fs.statSync(f).size);
}

check("stage1 = seed + 2", s1 === seed + 2, seed + " + 2 = " + s1);
check("stage2 = stage1^2", s2 === s1 * s1, s1 + "^2 = " + s2);
check("stage3 = stage2 - 4", s3 === s2 - 4, s2 + " - 4 = " + s3);
check("stage3 = (seed+2)^2 - 4", s3 === Math.pow(seed + 2, 2) - 4, String(s3));

// answer.json is built from the values read back from the saved stage files.
const answer = { stage1: s1, stage2: s2, stage3: s3 };
fs.writeFileSync("answer.json", JSON.stringify(answer, null, 2) + "\n");

// Re-read answer.json and confirm it round-trips to the same numeric values.
const reloaded = JSON.parse(fs.readFileSync("answer.json", "utf8"));
check("answer.json.stage1 matches stage1.txt", reloaded.stage1 === s1, String(reloaded.stage1));
check("answer.json.stage2 matches stage2.txt", reloaded.stage2 === s2, String(reloaded.stage2));
check("answer.json.stage3 matches stage3.txt", reloaded.stage3 === s3, String(reloaded.stage3));
check(
  "answer.json keys are numeric",
  ["stage1", "stage2", "stage3"].every((k) => typeof reloaded[k] === "number" && Number.isFinite(reloaded[k])),
  Object.keys(reloaded).join(",")
);
check(
  "answer.json has exactly the required keys",
  Object.keys(reloaded).sort().join(",") === "stage1,stage2,stage3",
  Object.keys(reloaded).sort().join(",")
);

if (failures.length > 0) {
  console.error("\nVERIFICATION FAILED: " + failures.length + " check(s)");
  process.exit(1);
}
console.log("\nALL CHECKS PASSED; wrote " + path.resolve("answer.json"));

